pragma solidity ^0.6.5;

import "./IERC20TokenV06.sol";

interface IEtherTokenV06 is IERC20TokenV06 {
  /// @dev Wrap ether.
  function deposit() external payable;

  /// @dev Unwrap ether.
  function withdraw(uint256 amount) external;
}

